Problem:
Two brothers, John and William, run a stand selling lemonade and brownies. A pitcher of lemonade takes 0.5 hours of John's time along with 0.2 hours of William's time. A batch of brownies take 1 hour of John's time and 0.5 hours of William's time. John has 10 hours available each day, but since William has hockey lessons, he only has 8 hours available each day. They get $20 profit per pitcher of lemonade, and $15 per batch of brownies. Formulate a LP to maximize profit.

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "pitchers of lemonade",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "batches of brownies",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "max",
   "terms": [
    {
     "var": "pitchers of lemonade",
     "coef": 20.0
    },
    {
     "var": "batches of brownies",
     "coef": 15.0
    }
   ]
  },
  "constraints": [
   {
    "name": "John's hours",
    "terms": [
     {
      "var": "pitchers of lemonade",
      "coef": 0.5
     },
     {
      "var": "batches of brownies",
      "coef": 1.0
     }
    ],
    "sense": "<=",
    "rhs": 10.0
   },
   {
    "name": "William's hours",
    "terms": [
     {
      "var": "pitchers of lemonade",
      "coef": 0.2
     },
     {
      "var": "batches of brownies",
      "coef": 0.5
     }
    ],
    "sense": "<=",
    "rhs": 8.0
   }
  ]
 },
 "facts": {
  "objective": 400.0,
  "values": {
   "pitchers of lemonade": 20.0,
   "batches of brownies": 0.0
  },
  "binding": [
   "John's hours"
  ],
  "slack": {
   "John's hours": 0.0,
   "William's hours": 4.0
  },
  "shadow_prices": null,
  "limits": {
   "John's hours": {
    "dropped_improves": true,
    "loosened_improves": true
   },
   "William's hours": {
    "dropped_improves": false,
    "loosened_improves": false
   }
  }
 }
}
